seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
# Let's try to detect tandem repeats with a window approach across whole seq.
# For each L, slide windows of 3*L and compute the best match fraction; report strong ones.
def tandem(L, w=None):
    if w is None: w=3*L
    best=(0,0)
    for i in range(0, len(seq)-w+1):
        m=0; t=0
        for j in range(w-L):
            t+=1
            if seq[i+j]==seq[i+j+L]: m+=1
        f=m/t
        if f>best[0]:
            best=(f,i)
    return best

for L in [60,65,70,71,72,73,74,75,76,77,78,80]:
    f,i=tandem(L)
    if f>0.5:
        print("L=%d best frac=%.2f at %d-%d"%(L,f,i+1,i+3*L))

seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
cons="GACGGCTTTGGTTACTAAGGG"   # 21-mer consensus
L=len(cons)
cand=[]
for i in range(len(seq)-L+1):
    w=seq[i:i+L]
    s=sum(1 for a,b in zip(w,cons) if a==b)
    cand.append((s,i))
# report all with score>=13 anywhere
peaks=[]
for s,i in cand:
    if s>=13: peaks.append((i+1,s))
merged=[]
for p,s in sorted(peaks):
    if merged and p-merged[-1][0]<=12:
        if s>merged[-1][1]: merged[-1]=(p,s)
    else:
        merged.append((p,s))
print("all windows score>=13 vs 21-mer consensus (whole seq):")
for p,s in merged:
    print("  start %d score %d/%d  %s"%(p,s,L, seq[p-1:p-1+L]))
print("count:", len(merged))
starts=[p for p,s in merged]
print("spacings:", [starts[i+1]-starts[i] for i in range(len(starts)-1)])

